      }

      /* compression suffix */
      func hasSuffix(_ suffix: String) -> Bool { name.count > suffix.utf8.count && name.suffix(suffix.utf8.count) == Array(suffix.utf8)[...] }
      if hasSuffix(".z") || hasSuffix(".Z") {
        name.removeLast(2)
      } else if hasSuffix(".gz") {
        name.removeLast(3)
      } else if hasSuffix(".bz2") {
        name.removeLast(4)
