      let nameText = String(decoding: name, as: UTF8.self)

      var unusual: Int32 = 0
      var bin: String? = nil
      var man: String? = nil

      if opts.opt_b {
        // Binaries have to match exactly, and must be regular executable files.
        unusual |= NO_BIN_FOUND
        for dir in opts.bindirs! {
          let candidate = "\(dir)/\(nameText)"
          var sb = stat()
